node.label:
html {
      font-family: sans-serif;
    }

    form {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      grid-column-gap: 5%;
      grid-row-gap: 10px;
      width: 508px;
      margin: 0 auto;
    }

    form label {
      grid-column: auto / span 2;
      text-align: right;
    }

    form input {
      width: 100%;
      grid-column: auto / span 3;
    }

    form p {
      grid-column: auto / span 5;
      grid-row: 4;
      color: #999;
      font-style: italic;
    }

